"""matplotlib._fontconfig_pattern — fontconfig string parser stub.

Real matplotlib parses fontconfig-style patterns like 'sans:bold'
into a FontProperties spec. The plotly backend uses CSS font-family
strings directly, so this module just round-trips its input.
"""


def parse_fontconfig_pattern(pattern):
    """Real impl returns a dict of font properties. Stub returns the
    raw pattern under 'family' so callers don't crash."""
    return {'family': [pattern]}


def generate_fontconfig_pattern(d):
    """Inverse of parse — emits a single family name."""
    if isinstance(d, dict):
        fam = d.get('family')
        if isinstance(fam, (list, tuple)) and fam:
            return str(fam[0])
        if fam: return str(fam)
    return str(d)
